// Real Chromium rendering with synthetic API fixtures. No live service calls.
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const http = require('node:http');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '../..');
const out = path.join(root, 'ci-results/enterprise-audit/browser');
const tools = path.join(os.tmpdir(), 'genai-audit-browser-tools/node_modules');
const { chromium } = require(path.join(tools, 'playwright-core'));
const AxeBuilder = require(path.join(tools, '@axe-core/playwright')).default;
const dist = path.join(os.tmpdir(), 'genai-ci-frontend/dist');
const checks = [], screens = [], network = [];
const profile = { authenticated: true, user_id: 'audit-user', name: 'Synthetic Auditor',
  email: 'auditor@example.test', role: 'Admin', roles: ['Admin', 'Member'], scope: ['audit.Admin', 'audit.Member'],
  session_id: 'synthetic-audit-session', login_time: '2026-11-24T00:00:00Z', source: 'synthetic-browser-fixture' };
const dataset = { id: 'audit', name: 'Synthetic Audit Fixture', currentVersion: 1, isActive: true,
  rowCount: 1, columnCount: 1, embeddingStatus: 'Ready', columns: [{ name: 'Amount', type: 'decimal' }] };
const widget = { definition: { id: 'total', revision: 1, semantic_revision: 1, dataset_id: 'audit', version: 1,
  title: 'Audited synthetic total', kind: 'kpi', status: 'approved', dependencies: ['Amount'], explanation: 'Synthetic fixture',
  query_plan: { metric: 'Amount', aggregation: 'SUM' } },
  result: { success: true, data: [{ Amount: 42 }], summary: { value: 42, formatted_value: '42' },
    records_matched: 1, execution_backend: 'synthetic', execution_time_ms: 1 } };

async function check(id, run) {
  const start = performance.now();
  try { checks.push({ id, status: 'PASS', detail: await run(), elapsed_ms: performance.now() - start }); }
  catch (error) { checks.push({ id, status: 'FAIL', detail: String(error.message).slice(0, 1800), elapsed_ms: performance.now() - start }); }
  console.log(`${checks.at(-1).status}: ${id}`);
}

async function main() {
  fs.mkdirSync(out, { recursive: true });
  const server = http.createServer((req, res) => {
    const requested = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    let file = path.resolve(dist, '.' + requested);
    if (!file.startsWith(path.resolve(dist) + path.sep) && file !== path.resolve(dist)) { res.writeHead(403).end(); return; }
    if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(dist, 'index.html');
    const types = { '.html': 'text/html', '.js': 'application/javascript', '.css': 'text/css', '.png': 'image/png', '.webp': 'image/webp', '.svg': 'image/svg+xml' };
    res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
    fs.createReadStream(file).pipe(res);
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const origin = `http://127.0.0.1:${server.address().port}`;
  const executablePath = ['C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
    'C:/Program Files/Google/Chrome/Application/chrome.exe'].find(p => fs.existsSync(p));
  const browser = await chromium.launch({ executablePath, headless: true });
  let scenario = 'empty', role = 'Admin', signedIn = true;
  let holdDashboard = false;
  const pendingDashboard = [];
  async function newPage(viewport) {
    const context = await browser.newContext({ viewport });
    const page = await context.newPage();
    page.setDefaultTimeout(15000);
    page.setDefaultNavigationTimeout(45000);
    const errors = [];
    page.on('pageerror', error => errors.push(String(error.message)));
    await page.route('**/*', async route => {
      const url = new URL(route.request().url());
      if (url.origin !== origin) { network.push({ host: url.hostname, action: 'blocked' }); await route.abort(); return; }
      if (!url.pathname.startsWith('/api/')) { await route.continue(); return; }
      const endpoint = url.pathname;
      if (endpoint === '/api/dashboard' && holdDashboard) {
        await new Promise(resolve => pendingDashboard.push(resolve));
      }
      let status = 200, body;
      if (endpoint === '/api/auth/me') {
        status = signedIn ? 200 : 401;
        body = signedIn ? { ...profile, role, roles: role === 'Admin' ? ['Admin', 'Member'] : ['Member'] } : { detail: 'Synthetic unauthenticated session' };
      } else if (scenario === 'error' && endpoint === '/api/dashboard') {
        status = 503; body = { detail: 'Synthetic audit outage' };
      } else if (endpoint === '/api/datasets') body = scenario === 'empty' ? [] : [dataset];
      else if (endpoint === '/api/datasets/active') body = { dataset: scenario === 'empty' ? null : dataset };
      else if (endpoint.includes('/semantics')) body = [{ dataset_id: 'audit', data_version: 1, revision: 1,
        status: 'approved', fields: [{ name: 'Amount', semantic_name: 'Amount', role: 'measure', type: 'decimal', aggregations: ['SUM'] }], relationships: [], derived_metrics: [] }];
      else if (endpoint === '/api/dashboard') body = { title: 'Synthetic browser audit', status: 'published', widgets: scenario === 'success' ? [widget] : [] };
      else if (endpoint === '/api/insights/dashboard') body = { title: '', items: [], status: 'unpublished' };
      else if (['/api/insights/recommendations', '/api/chat/sessions', '/api/system/connections', '/api/system/connector-types', '/api/system/bindings', '/api/system/jobs', '/api/system/audit'].includes(endpoint)) body = [];
      else if (endpoint === '/api/database/tables') body = { tables: [] };
      else if (endpoint === '/api/users') body = { users: [], total: 0, source: 'local_dev', project_role_collections: [], fetched_at: '2026-11-24T00:00:00Z' };
      else if (endpoint === '/api/health') body = { status: 'degraded', hana_connected: false, ai_core_connected: null, ai_core_configured: false };
      else { status = 503; body = { detail: 'Synthetic unavailable provider' }; }
      network.push({ path: endpoint, status, fixture: true });
      await route.fulfill({ status, contentType: 'application/json', body: JSON.stringify(body) });
    });
    return { context, page, errors };
  }
  async function capture(page, id, viewport, errors) {
    await page.waitForTimeout(200);
    const metrics = await page.evaluate(() => ({ width: innerWidth, scrollWidth: document.documentElement.scrollWidth,
      mainText: document.querySelector('main')?.textContent?.slice(0, 1200) || '', title: document.title }));
    const accessibility = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa']).analyze();
    const screenshot = `${id}-${viewport}.png`;
    await page.screenshot({ path: path.join(out, screenshot), fullPage: true });
    screens.push({ id, viewport, ...metrics, page_errors: [...errors], screenshot,
      accessibility_violations: accessibility.violations.map(v => ({ id: v.id, impact: v.impact, help: v.help,
        nodes: v.nodes.map(n => ({ target: n.target, failureSummary: n.failureSummary })) })) });
    return { screen: id, horizontal_overflow: metrics.scrollWidth > metrics.width + 1, page_errors: [...errors] };
  }
  try {
    const desktop = await newPage({ width: 1440, height: 1000 });
    const p = desktop.page;
    await p.goto(origin, { waitUntil: 'domcontentloaded' });
    await check('desktop_dashboard_empty_render', async () => {
      await p.locator('main').waitFor();
      assert.equal(desktop.errors.length, 0);
      return capture(p, 'dashboard-empty', 'desktop', desktop.errors);
    });
    const navigation = [
      ['Data Sources', /Data Sources/], ['Upload Files', /Dataset Ingestion|Data Studio/],
      ['Data Explorer', /Data Explorer/], ['AI Agents', /Enterprise AI Agents/],
      ['Build Your KPI', /Build Your KPI/], ['Widgets', /Widgets/],
      ['HANA Cloud Admin', /HANA|Synthetic unavailable provider/],
      ['Reports Library', /No saved reports are available/],
      ['System Management', /System Management/], ['Users', /User Management/],
    ];
    for (const [label, expected] of navigation) {
      await check('desktop_' + label.toLowerCase().replaceAll(' ', '_'), async () => {
        await p.getByRole('button', { name: new RegExp(label) }).first().click();
        await p.locator('main').filter({ hasText: expected }).waitFor();
        assert.equal(desktop.errors.length, 0);
        return capture(p, label.toLowerCase().replaceAll(' ', '-'), 'desktop', desktop.errors);
      });
      if (label === 'HANA Cloud Admin') {
        await check('hana_admin_does_not_claim_online_after_provider_error', async () => {
          await p.locator('main').getByText('Synthetic unavailable provider', { exact: true }).waitFor();
          assert.equal(await p.locator('main').getByText('Online', { exact: true }).count(), 0);
          return { provider_status: 503, online_badge: false };
        });
      }
    }
    await check('desktop_rag_panel_empty_render', async () => {
      await p.getByRole('button', { name: 'Open NEO Copilot', exact: true }).click();
      await p.locator('textarea').first().waitFor();
      assert.equal(desktop.errors.length, 0);
      return capture(p, 'rag-chat', 'desktop', desktop.errors);
    });
    await desktop.context.close();

    scenario = 'success';
    const success = await newPage({ width: 1440, height: 1000 });
    await check('dashboard_known_answer_42', async () => {
      await success.page.goto(origin, { waitUntil: 'domcontentloaded' });
      await success.page.getByText('Audited synthetic total', { exact: true }).first().waitFor();
      await success.page.getByText('42', { exact: true }).first().waitFor();
      return capture(success.page, 'dashboard-success', 'desktop', success.errors);
    });
    scenario = 'error';
    await check('dashboard_service_error_visible', async () => {
      await success.page.reload({ waitUntil: 'domcontentloaded' });
      await success.page.getByRole('alert').filter({ hasText: 'Synthetic audit outage' }).waitFor();
      return { visible_error: 'Synthetic audit outage' };
    });
    scenario = 'success';
    await check('dashboard_refresh_recovers_from_service_error', async () => {
      await success.page.getByRole('button', { name: /Refresh/ }).first().click();
      await success.page.getByText('Audited synthetic total', { exact: true }).first().waitFor();
      await success.page.getByText('42', { exact: true }).first().waitFor();
      return { recovered_value: 42 };
    });
    await success.context.close();

    holdDashboard = true;
    const loading = await newPage({ width: 1440, height: 1000 });
    await check('dashboard_loading_state_render_and_accessibility', async () => {
      await loading.page.goto(origin, { waitUntil: 'domcontentloaded' });
      await loading.page.locator('[aria-label="Loading executive dashboard"]').waitFor();
      return capture(loading.page, 'dashboard-loading', 'desktop', loading.errors);
    });
    holdDashboard = false;
    for (const resolve of pendingDashboard.splice(0)) resolve();
    await loading.page.getByText('Audited synthetic total', { exact: true }).first().waitFor();
    await loading.context.close();

    scenario = 'empty';
    const mobile = await newPage({ width: 390, height: 844 });
    await mobile.page.goto(origin, { waitUntil: 'domcontentloaded' });
    await check('mobile_dashboard_no_document_overflow', async () => {
      const observation = await capture(mobile.page, 'dashboard-empty', 'mobile', mobile.errors);
      assert.equal(observation.horizontal_overflow, false);
      return observation;
    });
    await check('mobile_navigation_to_data_explorer', async () => {
      await mobile.page.getByRole('button', { name: 'Toggle navigation menu', exact: true }).click();
      await mobile.page.getByRole('button', { name: /Data Explorer/ }).first().click();
      await mobile.page.locator('main').filter({ hasText: 'Data Explorer' }).waitFor();
      const observation = await capture(mobile.page, 'data-explorer', 'mobile', mobile.errors);
      assert.equal(observation.horizontal_overflow, false);
      return observation;
    });
    await mobile.context.close();

    role = 'Member';
    const member = await newPage({ width: 1440, height: 1000 });
    await member.page.goto(origin, { waitUntil: 'domcontentloaded' });
    await check('member_administration_navigation_hidden', async () => {
      assert.equal(await member.page.getByRole('button', { name: /HANA Cloud Admin/ }).count(), 0);
      assert.equal(await member.page.getByRole('button', { name: /System Management/ }).count(), 0);
      return { admin_navigation_buttons: 0, scope: 'UI only; synthetic identity' };
    });
    await check('member_hana_deep_link_denied_in_ui', async () => {
      await member.page.goto(origin + '/hanaadmin', { waitUntil: 'domcontentloaded' });
      await member.page.locator('main').filter({ hasText: /HANA Cloud Explorer|access denied|not authorized|permission required/i }).waitFor();
      const main = await member.page.locator('main').innerText();
      assert.match(main, /access denied|not authorized|permission required|administrat(?:or|ive) access required/i);
      return { denied: true, scope: 'UI only; backend access is separately enforced' };
    });
    await member.context.close();

    signedIn = false;
    const auth = await newPage({ width: 390, height: 844 });
    await check('unauthenticated_sign_in_screen', async () => {
      await auth.page.goto(origin, { waitUntil: 'domcontentloaded' });
      await auth.page.getByRole('heading', { name: 'Enterprise Sign In', exact: true }).waitFor();
      return capture(auth.page, 'sign-in', 'mobile', auth.errors);
    });
    await auth.context.close();
  } finally {
    await browser.close();
    await new Promise(resolve => server.close(resolve));
    const accessibility = screens.flatMap(s => s.accessibility_violations.map(v => ({ screen: s.id, viewport: s.viewport, ...v })));
    const results = { scope: 'Real Edge/Chromium, synthetic API fixtures; all non-loopback page requests blocked; no live auth/database/model integration',
      browser_executable: executablePath, checks, screens, accessibility, network,
      limitations: ['Partial state/viewport matrix only', 'External fonts and resources blocked', 'No live SAP integration', 'Automated axe checks do not establish full accessibility compliance'] };
    fs.writeFileSync(path.join(out, 'browser-results.json'), JSON.stringify(results, null, 2));
    console.log(JSON.stringify({ passed: checks.filter(c => c.status === 'PASS').length, failed: checks.filter(c => c.status === 'FAIL').length,
      accessibility_rule_ids: [...new Set(accessibility.map(v => v.id))] }));
  }
  process.exitCode = checks.some(c => c.status === 'FAIL') || screens.some(s => s.accessibility_violations.length) ? 1 : 0;
}
main().catch(error => { console.error(error); process.exitCode = 1; });

