"""Wrap the existing backend suite with disposable credential/token state."""

import os
import runpy
import sys
import tempfile
import unittest
from contextlib import ExitStack
from pathlib import Path
from unittest.mock import patch

from cryptography.fernet import Fernet

ROOT = Path(__file__).resolve().parents[2]


def main():
    sys.path.insert(0, str(ROOT / "backend"))
    with (
        tempfile.TemporaryDirectory(prefix="genai-audit-baseline-") as folder,
        ExitStack() as stack,
    ):
        stack.enter_context(
            patch.dict(
                os.environ, {"PLATFORM_CREDENTIAL_KEY": Fernet.generate_key().decode()}
            )
        )
        stack.enter_context(patch("dotenv.load_dotenv", return_value=False))
        stack.enter_context(patch("dotenv.dotenv_values", return_value={}))
        original_discover = unittest.defaultTestLoader.discover

        def discover(*args, **kwargs):
            from api.utils import calculate_token_usage

            stack.enter_context(
                patch.object(
                    calculate_token_usage, "LEDGER_FILE", Path(folder) / "tokens.jsonl"
                )
            )
            stack.enter_context(
                patch.object(calculate_token_usage, "ROOT_DIR", Path(folder))
            )
            return original_discover(*args, **kwargs)

        stack.enter_context(
            patch.object(unittest.defaultTestLoader, "discover", discover)
        )
        try:
            runpy.run_path(
                str(ROOT / "scripts/run_offline_tests.py"), run_name="__main__"
            )
        except SystemExit as exc:
            return int(exc.code or 0)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

audit_tool_sources.run_static_inventory.py:
"""Inspect source and reachable Git blobs without emitting secret values."""

import ast
import hashlib
import importlib.metadata
import json
import re
import subprocess
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "ci-results/enterprise-audit"


def git(*args):
    return subprocess.check_output(["git", *args], cwd=ROOT)


def main():
    files = [name for name in git("ls-files", "-z").decode().split("\0") if name]
    inventory, imports, tests, parse_errors, mutable_globals = [], {}, [], [], []
    hashes = defaultdict(list)
    for name in files:
        path = ROOT / name
        if not path.is_file():
            continue
        raw = path.read_bytes()
        inventory.append(
            {"path": name, "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}
        )
        if path.suffix in (".py", ".tsx", ".ts", ".js", ".sql") and raw.strip():
            hashes[hashlib.sha256(raw).hexdigest()].append(name)
        if path.suffix != ".py":
            continue
        try:
            tree = ast.parse(raw.decode("utf-8-sig"))
        except (SyntaxError, UnicodeError) as exc:
            parse_errors.append({"file": name, "error": type(exc).__name__})
            continue
        if name.startswith("backend/api/"):
            module = ".".join(Path(name).with_suffix("").parts[1:])
            imports[module] = [
                {"module": n.module, "line": n.lineno}
                for n in ast.walk(tree)
                if isinstance(n, ast.ImportFrom)
                and n.module
                and n.module.startswith("api.")
            ]
            for node in tree.body:
                if isinstance(node, (ast.Assign, ast.AnnAssign)) and isinstance(
                    node.value, (ast.Dict, ast.List, ast.Set)
                ):
                    mutable_globals.append(
                        {
                            "file": name,
                            "line": node.lineno,
                            "kind": type(node.value).__name__,
                        }
                    )
        if name.startswith("backend/tests/"):
            tests.extend(
                {"file": name, "test": n.name, "line": n.lineno}
                for n in ast.walk(tree)
                if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
                and n.name.startswith("test_")
            )

    graph = {
        name: {e["module"] for e in edges if e["module"] in imports}
        for name, edges in imports.items()
    }
    cycles = set()

    def visit(node, trail):
        if node in trail:
            cycle = trail[trail.index(node) :]
            cycles.add(min(tuple(cycle[i:] + cycle[:i]) for i in range(len(cycle))))
            return
        if len(trail) >= 8:
            return
        for target in sorted(graph.get(node, [])):
            if not trail or target >= trail[0]:
                visit(target, trail + [node])

    for name in graph:
        visit(name, [])

    patterns = {
        "private_key": re.compile(
            rb"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"
        ),
        "aws_access_key": re.compile(rb"\b(?:AKIA|ASIA)[A-Z0-9]{16}\b"),
        "github_token": re.compile(rb"\b(?:ghp_|gho_|ghs_)[A-Za-z0-9]{30,}\b"),
        "literal_secret_assignment": re.compile(
            rb"""(?i)(?:client_secret|clientsecret|api_key|password)\s*[=:]\s*["']([A-Za-z0-9_+/!@#$%^&*=-]{18,})["']"""
        ),
    }
    # cat-file batch avoids thousands of subprocesses on Windows. Only match metadata
    # is retained; raw blob bodies and matched values are never written to evidence.
    objects = {}
    for line in (
        git("rev-list", "--objects", "--all").decode(errors="replace").splitlines()
    ):
        oid, _, name = line.partition(" ")
        if name:
            objects[oid] = name
    payload = (
        b""
        if not objects
        else subprocess.check_output(
            ["git", "cat-file", "--batch"],
            input=("\n".join(objects) + "\n").encode(),
            cwd=ROOT,
        )
    )
    offset, blob_count = 0, 0
    indicators = []
    while offset < len(payload):
        end = payload.index(b"\n", offset)
        oid, kind, size = payload[offset:end].split()
        offset = end + 1
        size = int(size)
        raw = payload[offset : offset + size]
        offset += size + 1
        if kind != b"blob":
            continue
        blob_count += 1
        for rule, pattern in patterns.items():
            for match in pattern.finditer(raw):
                indicators.append(
                    {
                        "path": objects[oid.decode()],
                        "blob": oid.decode(),
                        "rule": rule,
                        "line": raw[: match.start()].count(b"\n") + 1,
                        "review": "indicator only; secret value omitted",
                    }
                )

    result = {
        "commit": git("rev-parse", "HEAD").decode().strip(),
        "tracked_files": len(files),
        "module_files": inventory,
        "test_inventory": tests,
        "python_parse_errors": parse_errors,
        "imports_including_deferred": imports,
        "import_cycles_including_deferred": [list(c) for c in sorted(cycles)],
        "exact_duplicate_nonempty_sources": [
            paths for paths in hashes.values() if len(paths) > 1
        ],
        "module_mutable_globals": mutable_globals,
        "history_blobs_scanned": blob_count,
        "secret_indicators": indicators,
        "secret_scan_limitations": "Patterns only, all reachable refs at audit time; no entropy scan or provider validation. No untracked credentials read. Zero matches does not prove absence of secrets.",
        "tracked_deployment_manifests": {
            name: name in files
            for name in (
                "mta.yaml",
                "xs-security.json",
                "backend/Procfile",
                "router/xs-app.json",
            )
        },
        "mta_ignored": subprocess.run(
            ["git", "check-ignore", "-q", "mta.yaml"], cwd=ROOT
        ).returncode
        == 0,
        "installed_python_versions": {
            d.metadata["Name"]: d.version
            for d in importlib.metadata.distributions()
            if d.metadata.get("Name")
        },
    }
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "source-inventory.json").write_text(
        json.dumps(result, indent=2), encoding="utf-8"
    )
    print(
        json.dumps(
            {
                "tracked_files": len(files),
                "python_parse_errors": len(parse_errors),
                "backend_test_methods": len(tests),
                "history_blobs_scanned": blob_count,
                "secret_indicators": len(indicators),
                "deferred_cycles": len(cycles),
            }
        )
    )
    return int(bool(parse_errors))


if __name__ == "__main__":
    raise SystemExit(main())
